import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import AurelinkDashboard from "./AurelinkDashboard";
import "./aurelink-workspace.css";

const API=(import.meta.env.VITE_API_BASE_URL as string|undefined)?.replace(/\/$/,"")||"https://redom-backend.onrender.com/redom-backend";
type Row=Record<string,any>;
type Page="overview"|"numbers"|"sms"|"email"|"activity"|"templates"|"contacts"|"campaigns"|"domains"|"senders"|"smtp"|"apikeys"|"senderids"|"verification"|"developer"|"reputation"|"billing"|"team"|"account";
const groups:{title:string;items:{id:Page;label:string}[]}[]=[
 {title:"WORKSPACE",items:[{id:"overview",label:"Overview"},{id:"numbers",label:"Phone numbers"}]},
 {title:"COMMUNICATIONS",items:[{id:"sms",label:"Send SMS"},{id:"email",label:"Send email"},{id:"activity",label:"Message activity"},{id:"templates",label:"Templates"},{id:"contacts",label:"Contacts & consent"},{id:"campaigns",label:"Campaigns"}]},
 {title:"EMAIL INFRASTRUCTURE",items:[{id:"domains",label:"Sending domains"},{id:"senders",label:"Email senders"},{id:"smtp",label:"SMTP keys"},{id:"apikeys",label:"API keys & MCP"},{id:"reputation",label:"Tracking & reputation"}]},
 {title:"IDENTITY & DEVELOPERS",items:[{id:"senderids",label:"SMS Sender IDs"},{id:"verification",label:"OTP verification"},{id:"developer",label:"Developer tools"},{id:"team",label:"Workspace team"}]},
 {title:"ACCOUNT",items:[{id:"billing",label:"Billing & usage"},{id:"account",label:"Account & security"}]}
];
function token(){return localStorage.getItem("aurelink.accessToken")||"";}
let refreshInFlight:Promise<string>|null=null;
async function refreshAccessToken():Promise<string>{
 if(!refreshInFlight){
  refreshInFlight=(async()=>{
   const refreshToken=localStorage.getItem("aurelink.refreshToken");
   if(!refreshToken)throw new Error("Your Aurelink session has expired.");
   const response=await fetch(API+"/aurelink/auth/refresh",{method:"POST",headers:{Accept:"application/json","Content-Type":"application/json"},body:JSON.stringify({refreshToken}),cache:"no-store"});
   const data=await response.json().catch(()=>({}));
   if(!response.ok||!data.success||!data.session?.accessToken||!data.session?.refreshToken)throw new Error(data.message||"Your Aurelink session has expired.");
   localStorage.setItem("aurelink.accessToken",data.session.accessToken);
   localStorage.setItem("aurelink.refreshToken",data.session.refreshToken);
   if(data.user)localStorage.setItem("aurelink.user",JSON.stringify(data.user));
   return data.session.accessToken as string;
  })().finally(()=>{refreshInFlight=null;});
 }
 return refreshInFlight;
}
function expireWorkspaceSession(){
 localStorage.removeItem("aurelink.accessToken");
 localStorage.removeItem("aurelink.refreshToken");
 localStorage.removeItem("aurelink.user");
 const next=window.location.pathname+window.location.search+window.location.hash;
 if(!window.location.pathname.startsWith("/login"))window.location.replace("/login?next="+encodeURIComponent(next));
}
async function api(path:string,method="GET",body?:unknown,headers:Record<string,string>={},retried=false){
 const send=async(access:string)=>fetch(API+path,{method,headers:{Accept:"application/json",...(access?{Authorization:"Bearer "+access}:{}),...(body!==undefined?{"Content-Type":"application/json"}:{}),...headers},body:body===undefined?undefined:JSON.stringify(body),cache:"no-store"});
 let r:Response;try{r=await send(token());}catch{throw new Error("Aurelink could not reach the service. Check your connection and retry.");}
 if(r.status===401&&!retried){
  try{const fresh=await refreshAccessToken();r=await send(fresh);}
  catch{expireWorkspaceSession();throw new Error("Your Aurelink session expired. Sign in again.");}
 }
 const d=await r.json().catch(()=>({}));
 if(r.status===401){expireWorkspaceSession();throw new Error("Your Aurelink session expired. Sign in again.");}
 if(!r.ok||d.success===false)throw new Error(d.message||"Aurelink could not complete this request.");
 return d;
}
const get=(p:string)=>api(p),post=(p:string,b:unknown,h:Record<string,string>={})=>api(p,"POST",b,h),patch=(p:string,b:unknown)=>api(p,"PATCH",b),del=(p:string)=>api(p,"DELETE");
const count=(v:unknown)=>Number(v||0).toLocaleString("en-US");
const dollars=(v:unknown)=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(Number(v||0));
const money=(v:unknown,c="USD")=>new Intl.NumberFormat("en-US",{style:"currency",currency:c}).format(Number(v||0)/100);
const date=(v:unknown)=>{if(!v)return "—";const d=new Date(String(v));return Number.isNaN(d.getTime())?String(v):d.toLocaleString("en-US",{month:"short",day:"numeric",year:"numeric",hour:"2-digit",minute:"2-digit"});};
const text=(v:unknown)=>String(v??"—");
function tone(v:unknown){const s=String(v||"unknown").toLowerCase();return /active|verified|approved|delivered|accepted|completed|opted_in|success/.test(s)?"good":/failed|rejected|bounced|suspended|revoked|opted_out/.test(s)?"bad":/pending|queued|review|unknown|reserved|scheduled/.test(s)?"wait":"neutral";}
function Badge({value}:{value:unknown}){return <span className={"aw-badge "+tone(value)}>{text(value).replace(/_/g," ")}</span>;}
function Icon({name}:{name:string}){const p:Record<string,ReactNode>={grid:<><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,phone:<><rect x="7" y="2" width="10" height="20" rx="2"/><path d="M11 18h2"/></>,message:<path d="M21 11.5a8.4 8.4 0 0 1-9 8.4 9 9 0 0 1-4-.9L3 21l1.8-4.5A8.4 8.4 0 1 1 21 11.5Z"/>,mail:<><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></>,activity:<path d="M3 12h4l3-8 4 16 3-8h4"/>,layers:<><path d="m12 3 9 5-9 5-9-5 9-5Z"/><path d="m3 12 9 5 9-5"/></>,users:<><path d="M16 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="10" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.9"/></>,globe:<><circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15 15 0 0 1 0 20M12 2a15 15 0 0 0 0 20"/></>,key:<><circle cx="8" cy="15" r="5"/><path d="m11.5 11.5 8-8L22 6l-2 2 2 2-3 3-2-2-4 4"/></>,shield:<><path d="M12 22s8-4 8-11V5l-8-3-8 3v6c0 7 8 11 8 11Z"/><path d="m9 12 2 2 4-4"/></>,code:<path d="m8 17-5-5 5-5M16 7l5 5-5 5M14 4l-4 16"/>,wallet:<><rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M16 15h2"/></>,user:<><circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/></>,send:<><path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/></>};return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{p[name]||p.grid}</svg>;}
function Load({label="Loading Aurelink data…"}:{label?:string}){return <div className="aw-loading" role="status"><span className="aw-spinner"/><b>{label}</b><small>Securely retrieving live account data</small></div>;}
function Notice({children,tone:kind="info"}:{children:ReactNode;tone?:"info"|"warn"|"error"|"success"}){return <div className={"aw-notice "+kind}>{children}</div>;}
function Button({children,onClick,kind="primary",disabled=false,type="button"}:{children:ReactNode;onClick?:()=>void;kind?:"primary"|"secondary"|"ghost"|"danger";disabled?:boolean;type?:"button"|"submit"}){return <button type={type} className={"aw-btn "+kind} disabled={disabled} onClick={onClick}>{children}</button>;}
function Field({label,name,placeholder="",type="text",required=false,full=false,children,defaultValue,help}:{label:string;name:string;placeholder?:string;type?:string;required?:boolean;full?:boolean;children?:ReactNode;defaultValue?:string|number;help?:string}){return <label className={"aw-field "+(full?"full":"")}><span>{label}</span>{children||<input name={name} type={type} placeholder={placeholder} required={required} defaultValue={defaultValue}/>}{help&&<small>{help}</small>}</label>;}
function Panel({title,subtitle,children,action}:{title:string;subtitle?:string;children:ReactNode;action?:ReactNode}){return <section className="aw-panel"><header><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>{children}</section>;}
function Heading({eyebrow,title,desc,action}:{eyebrow:string;title:string;desc:string;action?:ReactNode}){return <div className="aw-heading"><div><span>{eyebrow}</span><h1>{title}</h1><p>{desc}</p></div>{action}</div>;}
function Stat({label,value,detail,icon}:{label:string;value:ReactNode;detail:string;icon:string}){return <article className="aw-stat"><div><span>{label}</span><i><Icon name={icon}/></i></div><strong>{value}</strong><small>{detail}</small></article>;}
function Table({headers,rows,empty="No records yet."}:{headers:string[];rows:ReactNode[][];empty?:string}){return <div className="aw-table-wrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{v}</td>)}</tr>):<tr><td colSpan={headers.length}><div className="aw-empty"><b>{empty}</b>Records will appear here when Aurelink receives them.</div></td></tr>}</tbody></table></div>;}
function Overview({go}:{go:(p:Page)=>void}){const [d,setD]=useState<Row|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState("");const load=async()=>{setLoading(true);try{const [o,m,n,w]=await Promise.all([get("/aurelink/communications/overview"),get("/aurelink/communications/messages?limit=8"),get("/aurelink/orders"),get("/aurelink/wallet")]);setD({o,m,n,w});}catch(e){setError(e instanceof Error?e.message:"Unable to load overview.");}finally{setLoading(false);}};useEffect(()=>{void load();},[]);if(loading)return <Load/>;if(error)return <><Heading eyebrow="AURELINK OVERVIEW" title="Your workspace" desc="Communications, number services and account activity."/><Notice tone="error">{error}</Notice><Button onClick={()=>void load()}>Try again</Button></>;const o=d?.o||{},g=o.messages||[],sum=(c:string)=>g.filter((x:Row)=>x.channel===c).reduce((a:number,x:Row)=>a+Number(x.total||0),0),st=(s:string)=>g.filter((x:Row)=>x.status===s).reduce((a:number,x:Row)=>a+Number(x.total||0),0),failed=g.filter((x:Row)=>["failed","bounced","rejected"].includes(x.status)).reduce((a:number,x:Row)=>a+Number(x.total||0),0),pending=g.filter((x:Row)=>["pending","deferred","reserved","unknown"].includes(x.status)).reduce((a:number,x:Row)=>a+Number(x.total||0),0),orders=d?.n?.orders||[],recent=d?.m?.messages||[],providers=Object.entries(o.providers||{}) as [string,Row][],usage=o.usage||[],smsUnits=usage.filter((x:Row)=>x.channel==="sms").reduce((a:number,x:Row)=>a+Number(x.units||0),0),emailUnits=usage.filter((x:Row)=>x.channel==="email").reduce((a:number,x:Row)=>a+Number(x.units||0),0);return <><Heading eyebrow="COMMUNICATIONS OVERVIEW" title="Everything, connected." desc="One view of your phone numbers, messaging infrastructure and account activity." action={<Button onClick={()=>go("sms")}>Send a message</Button>}/><div className="aw-stats"><Stat label="Total messages" value={count(sum("sms")+sum("email"))} detail="Communications recorded" icon="activity"/><Stat label="Accepted" value={count(st("accepted"))} detail="Accepted by provider" icon="send"/><Stat label="Delivered" value={count(st("delivered"))} detail="Confirmed delivery" icon="shield"/><Stat label="Failed" value={count(failed)} detail="Failed or bounced" icon="activity"/></div><div className="aw-split"><Panel title="Communications activity" subtitle="SMS and Email · last 30 days"><div className="aw-bars">{[{label:"SMS",v:sum("sms")},{label:"Email",v:sum("email")}].map(x=><div key={x.label}><b>{count(x.v)}</b><i style={{height:Math.max(5,x.v/Math.max(1,sum("sms"),sum("email"))*100)+"%"}}/><small>{x.label}</small></div>)}</div><div className="aw-statuses">{[["Queued",st("queued")],["Pending",pending],["Delivered",st("delivered")],["Failed",failed]].map(([n,v])=><div key={String(n)}><span>{n}</span><b>{count(v)}</b></div>)}</div></Panel><Panel title="Existing number services" subtitle="Your current number-purchasing interface remains intact."><div className="aw-number-summary"><div><strong>{dollars(d?.w?.wallet?.balanceUsd)}</strong><small>Number wallet</small></div><div><strong>{count(orders.length)}</strong><small>Recent orders</small></div></div><div className="aw-number-types">{["activation","rental","dedicated"].map(k=><div key={k}><span>{k==="activation"?"Short-term":k==="rental"?"Long-term":"Dedicated"}</span><b>{count(orders.filter((x:Row)=>x.product_kind===k).length)}</b></div>)}</div><Button kind="secondary" onClick={()=>go("numbers")}>Open phone numbers workspace</Button></Panel></div><Panel title="Metered usage & consumption" subtitle="Billable units and recorded metered amounts from the communications usage ledger."><Table headers={["Channel","Status","Messages","Billable units","Metered amount"]} rows={usage.map((x:Row)=>[text(x.channel),<Badge value={x.status}/>,count(x.messages),count(x.units),money(x.metered_amount_minor,x.currency)])} empty="No communications usage has been recorded."/></Panel><div className="aw-stats"><Stat label="SMS billable units" value={count(smsUnits)} detail="Usage ledger segments" icon="message"/><Stat label="Email billable units" value={count(emailUnits)} detail="Usage ledger credits" icon="mail"/><Stat label="SMS messages" value={count(sum("sms"))} detail="Last 30 days" icon="send"/><Stat label="Email messages" value={count(sum("email"))} detail="Last 30 days" icon="mail"/></div><Panel title="Recent communications" subtitle="Latest messages recorded by Aurelink" action={<Button kind="ghost" onClick={()=>go("activity")}>View activity</Button>}><Table headers={["Recipient","Channel","Status","Created"]} rows={recent.map((x:Row)=>[<b>{text(x.recipient)}</b>,text(x.channel),<Badge value={x.status}/>,date(x.created_at)])} empty="No messages have been sent yet."/></Panel><div className="aw-split"><Panel title="Provider configuration" subtitle="Server-side readiness; provider secrets are never shown."><div className="aw-provider-list">{providers.flatMap(([c,p])=>Object.entries(p||{}).map(([n,v])=><div key={c+n}><span>{c.toUpperCase()} · {n.toUpperCase()}</span><Badge value={v?"configured":"not configured"}/></div>))}</div></Panel><Panel title="Quick actions"><div className="aw-quick"><button onClick={()=>go("sms")}><Icon name="message"/>Send SMS</button><button onClick={()=>go("email")}><Icon name="mail"/>Send email</button><button onClick={()=>go("domains")}><Icon name="globe"/>Verify a domain</button><button onClick={()=>go("developer")}><Icon name="code"/>Developer tools</button></div></Panel></div></>;}
function SmsPage(){const [countries,setCountries]=useState<Row[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[notice,setNotice]=useState(""),[category,setCategory]=useState("transactional");useEffect(()=>{get("/aurelink/communications/sms/countries").then(d=>setCountries(d.countries||[])).catch(e=>setNotice(e.message)).finally(()=>setLoading(false));},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=e.currentTarget,b=Object.fromEntries(new FormData(f).entries());setBusy(true);try{const r=await post("/aurelink/communications/sms/send",b,{"Idempotency-Key":crypto.randomUUID()});setNotice("SMS queued. Message ID: "+(r.message?.id||"created"));f.reset();}catch(x){setNotice(x instanceof Error?x.message:"Unable to queue SMS.");}finally{setBusy(false);}}return <><Heading eyebrow="SMS WORKSPACE" title="Send an SMS" desc="Aurelink validates destination, sender approval, consent and usage before queueing."/><Notice>Provider routing is managed by Aurelink. The customer send route does not accept a provider override. Marketing sends require recorded opt-in consent and an opt-out URL.</Notice><Panel title="Compose message" subtitle="Messages are queued for asynchronous provider delivery."><form className="aw-form" onSubmit={submit}><Field label="Recipient (E.164)" name="recipient" placeholder="+14155550123" type="tel" required/><Field label="Sender identity" name="sender" placeholder="Approved sender ID" required/><Field label="Destination country" name="countryCode" required><select name="countryCode" required disabled={loading}><option value="">{loading?"Loading countries…":"Select country"}</option>{countries.map(x=><option key={x.country_code} value={x.country_code}>{x.country_name} ({x.country_code})</option>)}</select></Field><Field label="Message category" name="category"><select name="category" value={category} onChange={e=>setCategory(e.target.value)}><option value="transactional">Transactional</option><option value="notification">Notification</option><option value="otp">OTP</option><option value="marketing">Marketing</option></select></Field><Field label="Message content" name="content" full required><textarea name="content" rows={6} maxLength={5000} placeholder="Write your SMS message…" required/></Field>{category==="marketing"&&<Field label="Opt-out URL" name="webUrl" type="url" placeholder="https://example.com/preferences" full required/>}<div className="aw-form-actions"><Button type="submit" disabled={busy||loading}>{busy?"Submitting securely…":"Queue SMS"}</Button></div></form>{notice&&<Notice tone={notice.includes("queued")?"success":"error"}>{notice}</Notice>}</Panel></>;}
function EmailPage(){const [senders,setSenders]=useState<Row[]>([]),[templates,setTemplates]=useState<Row[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[notice,setNotice]=useState("");useEffect(()=>{Promise.all([get("/aurelink/communications/email-senders"),get("/aurelink/communications/templates?channel=email")]).then(([s,t])=>{setSenders(s.senders||[]);setTemplates(t.templates||[]);}).catch(e=>setNotice(e.message)).finally(()=>setLoading(false));},[]);async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=e.currentTarget,b:any=Object.fromEntries(new FormData(f).entries()),files=[...((f.querySelector('input[type="file"]') as HTMLInputElement)?.files||[])];if(files.length>10){setNotice("A maximum of 10 attachments is allowed.");return;}try{setBusy(true);let total=0;b.attachments=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{total+=file.size;if(total>10*1024*1024){reject(new Error("Combined attachments may not exceed 10 MB."));return;}const reader=new FileReader();reader.onload=()=>resolve({filename:file.name,content:String(reader.result).split(",")[1],contentType:file.type||"application/octet-stream"});reader.onerror=()=>reject(new Error("Unable to read "+file.name));reader.readAsDataURL(file);})));if(!files.length)delete b.attachments;if(!b.templateId)delete b.templateId;const r=await post("/aurelink/communications/email/send",b,{"Idempotency-Key":crypto.randomUUID()});setNotice("Email queued. Message ID: "+(r.message?.id||"created"));f.reset();}catch(x){setNotice(x instanceof Error?x.message:"Unable to queue email.");}finally{setBusy(false);}}const verified=senders.filter(x=>x.status==="verified");return <><Heading eyebrow="MAIL WORKSPACE" title="Send an email" desc="Send transactional email from a verified sender identity."/><Notice>Provider routing is managed by Aurelink. CC, BCC, tags and attachments are supported. Domain and sender authorization are checked before queueing.</Notice><Panel title="Compose email"><form className="aw-form" onSubmit={submit}><Field label="Verified sender" name="sender" required><select name="sender" required disabled={loading}><option value="">Choose verified sender</option>{verified.map(x=><option key={x.id} value={x.email}>{x.email} · {x.sender_name}</option>)}</select></Field><Field label="Sender display name" name="senderName" placeholder="Aurelink Notifications" required/><Field label="Recipient" name="recipient" type="email" placeholder="customer@example.com" required/><Field label="Subject" name="subject" placeholder="Your update" full required/><Field label="Reply-To" name="replyTo" placeholder="support@example.com"/><Field label="CC" name="cc" placeholder="one@example.com, two@example.com"/><Field label="BCC" name="bcc" placeholder="audit@example.com"/><Field label="Tags" name="tags" placeholder="transactional, onboarding"/><Field label="Template" name="templateId"><select name="templateId"><option value="">No template</option>{templates.filter(x=>x.status==="active").map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="Plain-text body" name="text" full><textarea name="text" rows={4} placeholder="Write your email…"/></Field><Field label="HTML body" name="html" full><textarea name="html" rows={6} placeholder="<p>Hello {{firstName}}</p>"/></Field><Field label="Attachments (optional)" name="attachments" full help="Up to 10 files / 10 MB combined."><input type="file" multiple/></Field><div className="aw-form-actions"><Button type="submit" disabled={busy||loading||verified.length===0}>{busy?"Queueing email…":"Queue email"}</Button></div></form>{!loading&&!verified.length&&<Notice tone="warn">No verified sender identity is available. Verify a domain and create a sender first.</Notice>}{notice&&<Notice tone={notice.includes("queued")?"success":"error"}>{notice}</Notice>}</Panel></>;}
function ActivityPage(){const [rows,setRows]=useState<Row[]>([]),[loading,setLoading]=useState(true),[channel,setChannel]=useState(""),[status,setStatus]=useState(""),[search,setSearch]=useState(""),[notice,setNotice]=useState(""),[detail,setDetail]=useState<Row|null>(null);const load=async()=>{setLoading(true);try{const q=new URLSearchParams({limit:"100"});if(channel)q.set("channel",channel);if(status)q.set("status",status);const d=await get("/aurelink/communications/messages?"+q);setRows(d.messages||[]);}catch(e){setNotice(e instanceof Error?e.message:"Unable to load messages.");}finally{setLoading(false);}};useEffect(()=>{void load();},[channel,status]);const visible=rows.filter(x=>JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));async function retry(id:string){try{await post("/aurelink/communications/messages/"+id+"/retry",{},{"Idempotency-Key":crypto.randomUUID()});setNotice("Retry accepted.");void load();}catch(e){setNotice(e instanceof Error?e.message:"Retry failed.");}}async function inspect(id:string){try{const r=await get("/aurelink/communications/messages/"+id);setDetail(r.message||r);}catch(e){setNotice(e instanceof Error?e.message:"Unable to retrieve message.");}}return <><Heading eyebrow="COMMUNICATIONS LOG" title="Message activity" desc="Search message history, provider acceptance, delivery status and retry eligibility."/><div className="aw-toolbar"><input placeholder="Search recipient, subject or ID" value={search} onChange={e=>setSearch(e.target.value)}/><select value={channel} onChange={e=>setChannel(e.target.value)}><option value="">All channels</option><option value="sms">SMS</option><option value="email">Email</option></select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">All statuses</option>{["queued","accepted","delivered","failed","bounced","deferred","pending"].map(x=><option key={x}>{x}</option>)}</select><Button kind="secondary" onClick={()=>void load()}>Refresh</Button></div>{detail&&<Panel title={"Message details · "+text(detail.id)} action={<Button kind="ghost" onClick={()=>setDetail(null)}>Close</Button>}><pre className="aw-code">{JSON.stringify(detail,null,2)}</pre></Panel>}{loading?<Load label="Loading message history…"/>:<Table headers={["Recipient","Channel","Subject / category","Provider","Status","Created","Actions"]} rows={visible.map(x=>[<b>{text(x.recipient)}</b>,text(x.channel),text(x.subject||x.category),text(x.provider),<Badge value={x.status}/>,date(x.created_at),<div className="aw-actions"><Button kind="ghost" onClick={()=>void inspect(x.id)}>Details</Button>{["failed","bounced","rejected"].includes(x.status)&&<Button kind="secondary" onClick={()=>void retry(x.id)}>Retry</Button>}</div>])} empty="No messages match these filters."/>}{notice&&<Notice>{notice}</Notice>}</>;}
