 const [domains,setDomains]=useState<Row[]>([]),[rows,setRows]=useState<Row[]>([]),[smtp,setSmtp]=useState<Row>({}),[loading,setLoading]=useState(true),[notice,setNotice]=useState(""),[secret,setSecret]=useState<Row|null>(null),[search,setSearch]=useState(""),[selected,setSelected]=useState<string[]>([]),[verifyPurpose,setVerifyPurpose]=useState<"smtp_credential_create"|"smtp_credential_rotate"|null>(null),[pending,setPending]=useState<Row|null>(null),[formData,setFormData]=useState<Row>({domainId:"",label:""});
