 useEffect(()=>{void load();},[]);
 async function createProject(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,b=Object.fromEntries(new FormData(form).entries());try{await post("/aurelink/account/projects",b);form.reset();setNotice("Developer project created.");void load();}catch(x){setNotice(x instanceof Error?x.message:"Unable to create project.");}}
 async function updateProject(x:Row){const name=prompt("Project name",String(x.name||""));if(name===null)return;const description=prompt("Project description",String(x.description||""));if(description===null)return;const status=prompt("Project status: active, suspended or archived",String(x.status||"active"));if(status===null)return;if(!["active","suspended","archived"].includes(status)){setNotice("Choose active, suspended or archived.");return;}try{await patch("/aurelink/account/projects/"+x.id,{name,description,status});setNotice("Project updated.");void load();}catch(e){setNotice(e instanceof Error?e.message:"Unable to update project.");}}
 async function createKey(e:FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,data=new FormData(form),scopes=[...form.querySelectorAll<HTMLInputElement>('input[name="scopes"]:checked')].map(x=>x.value);if(!scopes.length){setNotice("Select at least one API permission.");return;}const body={label:String(data.get("label")||""),environment:String(data.get("environment")||"live"),projectId:String(data.get("projectId")||"")||null,scopes,rateLimitPerMinute:Number(data.get("rateLimitPerMinute")||60),expiresInDays:Number(data.get("expiresInDays")||0)};setPendingKeyAction({body,form});setKeyVerification("api_key_create");}
