 async function editKey(x:Row){const label=prompt("API key label",String(x.label||""));if(label===null)return;const scopesValue=prompt("Permissions, comma-separated: communications:read, communications:send, verify:write",Array.isArray(x.scopes)?x.scopes.join(", "):"communications:read");if(scopesValue===null)return;const scopes=scopesValue.split(",").map(v=>v.trim()).filter(v=>scopeOptions.includes(v));if(!scopes.length){setNotice("Select at least one supported permission.");return;}const rate=Number(prompt("Requests per minute (1–6000)",String(x.rate_limit_per_minute||60)));if(!Number.isFinite(rate)||rate<1||rate>6000){setNotice("Rate limit must be between 1 and 6000 requests per minute.");return;}try{await patch("/aurelink/account/api-keys/"+x.id,{label,scopes,rateLimitPerMinute:Math.floor(rate)});setNotice("API key configuration updated.");void load();}catch(e){setNotice(e instanceof Error?e.message:"Unable to update API key.");}}
